const VERSION = 'everywhen-c44c10d32a';
const ASSETS = ["./","./index.html","./manifest.webmanifest","./icons/apple-touch-icon.png","./icons/icon-192.png","./icons/icon-512.png","./images/photos/buivien.jpg","./images/photos/bund.jpg","./images/photos/cruise.jpg","./images/photos/disney.jpg","./images/photos/f-banhmi.jpg","./images/photos/f-biluochun.jpg","./images/photos/f-buncha.jpg","./images/photos/f-chaca.jpg","./images/photos/f-cifan.jpg","./images/photos/f-comtam.jpg","./images/photos/f-dongpo.jpg","./images/photos/f-eggcoffee.jpg","./images/photos/f-hongshao.jpg","./images/photos/f-lanzhou.jpg","./images/photos/f-ljshrimp.jpg","./images/photos/f-noodle.jpg","./images/photos/f-phobo.jpg","./images/photos/f-phosgn.jpg","./images/photos/f-pianerchuan.jpg","./images/photos/f-sjb.jpg","./images/photos/f-squirrel.jpg","./images/photos/f-sznoodle.jpg","./images/photos/f-tangyuan.jpg","./images/photos/f-wonton.jpg","./images/photos/f-xlb.jpg","./images/photos/hefang.jpg","./images/photos/hoankiem.jpg","./images/photos/jingan.jpg","./images/photos/leifeng.jpg","./images/photos/lingering.jpg","./images/photos/lingyin.jpg","./images/photos/longjing.jpg","./images/photos/lujiazui.jpg","./images/photos/museum.jpg","./images/photos/nanjing.jpg","./images/photos/nguyenhue.jpg","./images/photos/oldq.jpg","./images/photos/pingjiang.jpg","./images/photos/qibao.jpg","./images/photos/shantang.jpg","./images/photos/stay-han-0.jpg","./images/photos/stay-han-1.jpg","./images/photos/stay-hz-0.jpg","./images/photos/stay-hz-1.jpg","./images/photos/stay-sgn-0.jpg","./images/photos/stay-sgn-1.jpg","./images/photos/stay-sh-0.jpg","./images/photos/stay-sh-1.jpg","./images/photos/stay-sh-2.jpg","./images/photos/stay-sh-3.jpg","./images/photos/stay-sh-4.jpg","./images/photos/stay-sz-0.jpg","./images/photos/stay-sz-1.jpg","./images/photos/szmuseum.jpg","./images/photos/temple.jpg","./images/photos/tigerhill.jpg","./images/photos/trainst.jpg","./images/photos/tzf.jpg","./images/photos/westlake.jpg","./images/photos/wukang.jpg","./images/photos/xtd.jpg","./images/photos/yuyuan.jpg","./images/photos/zjj.jpg","./images/photos/zzy.jpg"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});

// Same-origin files: serve from cache straight away, refresh the cache in the background.
// Other hosts (weather, exchange rates) go straight to the network; the app handles failures itself.
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  e.respondWith(caches.open(VERSION).then(async cache => {
    const hit = await cache.match(req, { ignoreSearch: true }) || (req.mode === 'navigate' ? await cache.match('./index.html') : undefined);
    const net = fetch(req).then(res => { if (res.ok) cache.put(req, res.clone()); return res; }).catch(() => undefined);
    return hit || (await net) || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
  }));
});
